package com.ghostipedia.cosmiccore.common.machine.multiblock.multi;

/**
 * Star Ladder Research Hub structure patterns for tiers T0-T3.
 * Characters have been normalized across all tiers for consistency.
 * Each string in the array is one aisle, with layers separated by '|'.
 *
 * UNIFIED LEGEND (applies to all tiers):
 * ' ' (space) = Air/ANY
 * '@' = Controller marker (orange_wool from export)
 * '#' = Controller position (red_wool from export)
 * A = cosmiccore:superheavy_steel_casing
 * B = cosmiccore:bolted_heavy_frame_casing
 * C = cosmiccore:somarust_casing
 * D = cosmiccore:soul_muted_casing
 * E = cosmiccore:bichromal_nevramite_casing (T1+)
 * F = cosmiccore:oscillating_gilded_pthanterum_casings (T2+)
 * G = cosmiccore:highly_flexible_reinforced_trinavine_casing (T2+)
 * H = cosmiccore:royal_ichorium_casing (T3+)
 * I = cosmiccore:multi_purpose_interstellar_grade_casing (T3+)
 * J = cosmiccore:ultra_powered_casing (T3+)
 */
